  if (args.limit) {
    // Spread the limit across the corpus so a small self-check still touches every group.
    const step = Math.max(1, Math.floor(corpus.length / args.limit));
    corpus = corpus.filter((_, i) => i % step === 0).slice(0, args.limit);
  }

