    const { status, chunks } = classify(p.value, outside);
    const mine = piiSpans.find((x) => x.p === p)!.spans;
    const caughtBy = [...new Set(
      redactions.filter((r) => {
        const rs = occurrences(c.text, r.original.trim() || r.original);
